// Box2 patcher: the "More filters" data for the buyer /search panel as ANCHORED edits to the box's own deals-api files: fuel / drivetrain / transmission (inferred from
// text), body style, dealer, mileage minimum and VIN pattern as list-query filters, a `filtersApplied` echo on list calls, and GET /api/inventory/facet-counts (live
// counts for those chips plus year, mileage and days on market). Code only until Paul types GO. Never restarts anything, never sets a flag, never touches the database.
// Generated by scripts/box/gen-filter-panel-patch.mjs from scripts/box/filter-panel-edits.json and the two modules in scrapers/lightsail-crawler/src; do not edit by hand.
//
//   node 2026-10-27-filter-panel.mjs [--dir=/opt/trimscout-deals/src] [--apply]
//
// What it changes, and nothing else:
//   inventoryListQuery.js   odometerMin, bodyStyle, dealerId (several), fuel, drivetrain, transmission (only with a make), vinPattern; `filtersApplied` in the result
//   deals_api_server.js     import, GET /api/inventory/facet-counts (gate: FACET_COUNTS_MAX_CONCURRENT, row cap: FACET_COUNTS_ROW_CAP), `filtersApplied` echoed on list calls
//   inventoryDerived.js     NEW module: the fuel / drivetrain / transmission text rules (SQL and JS from one set of patterns), VIN pattern and value cleaners
//   facetCounts.js          NEW module: the facet counts logic
// Prerequisites: 2026-10-26-facet-extras.mjs is installed (facetExtras.js exists, inventoryListQuery.js already has excludeTerms) and the options-paid-only patch; this refuses otherwise.
//
// Without --apply it is a DRY RUN: it reads the files, checks every anchor (each "find" must occur EXACTLY once, or the edit's marker must already be there),
// stages the patched modules in a temp dir, loads them and runs smoke checks, and writes nothing to --dir. With --apply it
//   1. writes patched copies to <file>.new.mjs and node --check's them,
//   2. copies each original to <file>.bak.<timestamp> (cp -p), moves the new file into place (same mode), and installs the two new modules.
// Takes effect at the next deals-api restart (idle window, Paul's call). There is no flag: the new filters are inert until the web app sends them, and the new route
// only runs when it is asked.
//
// RESTORE: for each backup the apply printed: cp -p <file>.bak.<STAMP> <file>   (files: deals_api_server.js inventoryListQuery.js); then rm inventoryDerived.js facetCounts.js;
//   then restart only if deals-api was already restarted onto the new code. All at once:
//   cd <dir> && for f in deals_api_server inventoryListQuery; do cp -p $f.js.bak.<STAMP> $f.js; done; rm -f inventoryDerived.js facetCounts.js
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { pathToFileURL } from "node:url";

const args = Object.fromEntries(process.argv.slice(2).map((a) => { const [k, ...v] = a.replace(/^--/, "").split("="); return [k, v.length ? v.join("=") : true]; }));
const DIR = path.resolve(args.dir || "/opt/trimscout-deals/src");
const APPLY = Boolean(args.apply);
const STAMP = new Date().toISOString().replace(/[-:T]/g, "").slice(0, 14);
const count = (hay, needle) => { let n = 0, i = 0; while ((i = hay.indexOf(needle, i)) >= 0) { n++; i += needle.length; } return n; };

const EDITS = /*EDITS*/null;
for (const e of EDITS) if (e.find.includes(e.marker) || !e.replace.includes(e.marker)) throw new Error(`edit ${e.id}: marker must be in the replacement and not in the anchor`);

const MODULES = /*MODULES*/null; // { "inventoryDerived.js": text, "facetCounts.js": text }

// ---- prerequisites on the box ----
for (const f of [...new Set(EDITS.map((e) => e.file))]) if (!fs.existsSync(path.join(DIR, f))) { console.error(`ABORT: ${path.join(DIR, f)} is missing - is --dir the box's src directory? Nothing written.`); process.exit(2); }
if (!fs.existsSync(path.join(DIR, "optionsPaidOnlyServer.js"))) { console.error("ABORT: optionsPaidOnlyServer.js is missing - apply 2026-10-19-options-paid-only.mjs first. Nothing written."); process.exit(2); }
if (!fs.existsSync(path.join(DIR, "facetExtras.js"))) { console.error("ABORT: facetExtras.js is missing - apply 2026-10-26-facet-extras.mjs first (this builds on its inventoryListQuery.js). Nothing written."); process.exit(2); }

const files = [...new Set(EDITS.map((e) => e.file))];
const plan = [];
let abort = false;
for (const f of files) {
  const p = path.join(DIR, f);
  const original = fs.readFileSync(p, "utf8");
  let text = original;
  for (const e of EDITS.filter((x) => x.file === f)) {
    const nFind = count(text, e.find), nMark = count(text, e.marker);
    let status;
    if (nMark >= 1) status = nMark === 1 ? "already applied" : `MARKER PROBLEM: marker occurs ${nMark}x`;
    else if (nFind === 1) { text = text.replace(e.find, () => e.replace); status = "will apply"; }
    else status = `ANCHOR PROBLEM: find occurs ${nFind}x, marker ${nMark}x`;
    if (/PROBLEM/.test(status)) abort = true;
    console.log(`${f} :: ${e.id} :: ${status}`);
  }
  plan.push({ f, p, original, text });
}
if (abort) { console.error("ABORT: nothing written. (The box's file differs from the repo's at that anchor: send me the lines around it.)"); process.exit(2); }

// Stage the patched modules in a temp dir and exercise them.
const stage = fs.mkdtempSync(path.join(os.tmpdir(), "filterpanel-stage-"));
const verify = async () => {
  fs.writeFileSync(path.join(stage, "package.json"), JSON.stringify({ type: "module" }));
  for (const f of fs.readdirSync(DIR)) if (/\.(js|json)$/.test(f) && f !== "package.json") fs.copyFileSync(path.join(DIR, f), path.join(stage, f));
  for (const x of plan) fs.writeFileSync(path.join(stage, x.f), x.text);
  for (const [name, text] of Object.entries(MODULES)) fs.writeFileSync(path.join(stage, name), text);
  execFileSync(process.execPath, ["--check", path.join(stage, "deals_api_server.js")], { stdio: "pipe" });
  const imp = (f) => import(pathToFileURL(path.join(stage, f)).href);
  const dv = await imp("inventoryDerived.js"), fc = await imp("facetCounts.js"), lq = await imp("inventoryListQuery.js");
  const server = plan.find((x) => x.f === "deals_api_server.js").text;
  const q = (s) => lq.inventoryListQuery(new URLSearchParams(s));

  // 1. a query without any of the new params is the same query as before: no new predicate, nothing reported applied
  const plain = q("make=Toyota&inStock=1&retailOnly=1&model=RAV4&priceMax=40000");
  if (plain.filtersApplied.length || /REGEXP|body_style|vin LIKE|vin_rev|i\.mileage >=/.test(plain.countSql)) throw new Error("a query without the new filters changed");
  if (!/i\.dealer_id = \?/.test(q("make=Toyota&dealerId=7").countSql)) throw new Error("a single dealerId is no longer `i.dealer_id = ?`");
  // 2. the new predicates are there, the derived ones only with a make, junk is dropped
  const all = q("make=Toyota&inStock=1&fuel=hybrid&drivetrain=awd&transmission=cvt&bodyStyle=SUV&odometerMin=5000&dealerId=3&dealerId=4&vinPattern=JTM*");
  if (all.filtersApplied.slice().sort().join() !== "bodyStyle,dealerId,drivetrain,fuel,odometerMin,transmission,vinPattern") throw new Error("filtersApplied is wrong: " + all.filtersApplied);
  if (q("state=NJ&inStock=1&fuel=hybrid").filtersApplied.length) throw new Error("fuel honoured without a make");
  if (q("make=Toyota&fuel=rocket").filtersApplied.length) throw new Error("an unknown fuel was honoured");
  // 3. the text rules
  if (dv.classifyFuel({ trim: "XSE Hybrid", engine: "2.5L" }) !== "hybrid" || dv.classifyDrivetrain({ trim: "XLT 4x4" }) !== "awd" || dv.classifyTransmission({ transmission: "CVT" }) !== "cvt" || dv.classifyFuel({ trim: "LE" }) !== null) throw new Error("text rules misclassify");
  // 4. the facet counts: each list leaves out its own filter; a set over the cap is "too broad"
  const rows = [{ year: 2025, mileage: 10, body: "SUV", days: 3, dealer_id: 1, dealer_name: "A", fuel: "gas", drive: "awd", trans: "cvt" }, { year: 2024, mileage: 90000, body: "SUV", days: 40, dealer_id: 2, dealer_name: "B", fuel: "hybrid", drive: "awd", trans: "cvt" }];
  const dims = fc.foldFacetCounts(rows, { ...fc.facetedFiltersOf(new URLSearchParams("make=Toyota&fuel=hybrid")) });
  if (dims.fuel.length !== 2 || dims.year.length !== 1) throw new Error("facet counts misfold");
  if (!fc.buildFacetCountsResponse(new Array(11).fill(rows[0]), 10, {}).tooBroad) throw new Error("the row cap does not answer too broad");
  // 5. the route is wired and gated
  for (const needle of ['pathname === "/api/inventory/facet-counts"', "const facetCountsGate = createGate(", "body.filtersApplied = filtersApplied;"]) if (!server.includes(needle)) throw new Error("server wiring missing: " + needle);
  console.log("staged modules load; queries without the new params unchanged; derived filters need a make; facet counts fold and cap; route wired");
};
try { await verify(); } catch (err) { console.error(`ABORT (nothing written to ${DIR}): ${err.message}`); fs.rmSync(stage, { recursive: true, force: true }); process.exit(3); }
fs.rmSync(stage, { recursive: true, force: true });
if (!APPLY) { console.log("DRY RUN ok - nothing written. Re-run with --apply."); process.exit(0); }

const staged = [];
try {
  for (const x of plan) {
    if (x.text === x.original) { console.log(`${x.f}: nothing to change`); continue; }
    const newPath = path.join(DIR, x.f.replace(/\.js$/, ".new.mjs"));
    staged.push({ ...x, newPath });
    fs.writeFileSync(newPath, x.text);
    execFileSync(process.execPath, ["--check", newPath], { stdio: "pipe" });
  }
} catch (err) {
  for (const x of staged) fs.rmSync(x.newPath, { force: true });
  console.error(`ABORT (originals untouched, temp files removed): ${err.message}`);
  process.exit(3);
}
for (const x of staged) {
  const bak = `${x.p}.bak.${STAMP}`;
  fs.copyFileSync(x.p, bak); fs.chmodSync(bak, fs.statSync(x.p).mode);
  fs.chmodSync(x.newPath, fs.statSync(x.p).mode);
  fs.renameSync(x.newPath, x.p);
  console.log(`${x.f}: backup ${bak}; patched file in place. Rollback: cp -p ${bak} ${x.p}`);
}
for (const [name, text] of Object.entries(MODULES)) {
  const mp = path.join(DIR, name);
  if (fs.existsSync(mp) && fs.readFileSync(mp, "utf8") === text) { console.log(`${name}: already installed, unchanged.`); continue; }
  if (fs.existsSync(mp)) { fs.copyFileSync(mp, `${mp}.bak.${STAMP}`); console.log(`${name}: existing file backed up to ${mp}.bak.${STAMP}`); }
  fs.writeFileSync(mp + ".new", text); fs.chmodSync(mp + ".new", 0o664); fs.renameSync(mp + ".new", mp);
  console.log(`${name}: installed (${mp}). Rollback: rm it, or restore the .bak.`);
}
console.log(`DONE (backup stamp ${STAMP}). deals-api has NOT been restarted; the new code loads at the next restart (nothing else to set).`);
